import { expect, test, type Page } from "@playwright/test";

// Credentials per role come from the UAT secret (never committed). TOTP codes are generated by the tester.
const users = {
  loan_officer: process.env.E2E_OFFICER_USER,
  underwriter: process.env.E2E_UNDERWRITER_USER,
} as const;
const PASSWORD = process.env.E2E_STAFF_PASSWORD ?? "";
const TOTP = process.env.E2E_STAFF_TOTP ?? "";

async function signIn(page: Page, user: string) {
  await page.goto("/auth/login");
  await page.getByLabel(/username|email/i).fill(user);
  await page.getByLabel(/password/i).fill(PASSWORD);
  await page.getByRole("button", { name: /sign in/i }).click();
  await page.getByLabel(/one-time code/i).fill(TOTP);
  await page.getByRole("button", { name: /sign in|submit/i }).click();
  await page.waitForURL((url) => !url.hostname.startsWith("auth."));
}

test("loan officer sees no decide buttons and no score (ADR-0013, UAT-06c)", async ({ page }) => {
  test.skip(!users.loan_officer, "E2E_OFFICER_USER not set");
  await signIn(page, users.loan_officer!);
  await page.goto(`/cases/${process.env.E2E_OFFICER_CASE_ID ?? "B1"}`);
  await expect(page.getByText("Reasons the customer sees")).toBeVisible();
  await expect(page.getByRole("button", { name: /approve|reject/i })).toHaveCount(0);
  await expect(page.getByText(/P\(default\)/)).toHaveCount(0);
});

test("underwriter cannot open their own submission (E11 AC5)", async ({ page }) => {
  test.skip(!users.underwriter, "E2E_UNDERWRITER_USER not set");
  await signIn(page, users.underwriter!);
  await page.goto("/reviews");
  await expect(page.getByRole("heading", { name: /review queue/i })).toBeVisible();
});

test("every page sends a strict CSP (E12 AC5)", async ({ request }) => {
  const response = await request.get("/forbidden");
  expect(response.headers()["content-security-policy"]).toContain("frame-ancestors 'none'");
});
